//! Join results checked against DuckDB 1.5.6 (`SET threads=1`), including row order where
//! DuckDB's is deterministic and the plans match.
#![allow(clippy::unwrap_used)]

use rustdb::{Connection, Database};

const SETUP: &[&str] = &[
    "CREATE TABLE l AS SELECT i, CASE WHEN i % 5 = 0 THEN NULL ELSE i % 7 END AS k, 'l' || i AS s FROM range(40) t(i)",
    "CREATE TABLE r AS SELECT i, CASE WHEN i % 6 = 0 THEN NULL ELSE i % 4 END AS k, 'r' || i AS s FROM range(30) t(i)",
    "CREATE TABLE a AS SELECT i, (i * 7919) % 3001 AS k, (i * 104729) % 3011 AS m FROM range(3000) t(i)",
    "CREATE TABLE b AS SELECT i, (i * 6007) % 2503 AS k, (i * 1009) % 2521 AS m FROM range(2500) t(i)",
    "CREATE TABLE trades AS SELECT * FROM (VALUES (1, 10), (1, NULL), (2, 5), (NULL, 7), (1, 3), (2, 1)) t(g, ts)",
    "CREATE TABLE prices AS SELECT * FROM (VALUES (1, 1, 'a'), (1, 4, 'b'), (2, 2, 'c'), (NULL, 1, 'd'), (1, NULL, 'e')) t(g, ts, v)",
];

fn connect() -> Connection {
    let mut connection = Database::open_in_memory().unwrap().connect().unwrap();
    for statement in SETUP {
        connection.query(statement).unwrap();
    }
    connection
}

/// The rows of `sql`, NULL as "NULL", like the CSV output of the DuckDB CLI.
fn rows(sql: &str) -> Vec<Vec<String>> {
    let result = connect().query(sql).unwrap();
    (0..result.row_count())
        .map(|row| {
            (0..result.column_count())
                .map(|column| {
                    let value = result.value(column, row);
                    if value.is_null() {
                        "NULL".to_owned()
                    } else {
                        value.to_varchar().unwrap()
                    }
                })
                .collect()
        })
        .collect()
}

fn expect(sql: &str, expected: &str) {
    let expected: Vec<Vec<String>> = expected
        .lines()
        .filter(|line| !line.is_empty())
        .map(|line| line.split(',').map(str::to_owned).collect())
        .collect();
    assert_eq!(rows(sql), expected, "{sql}");
}

