#[test]
fn iejoin_left_outer() {
    expect(
        "SELECT a.i, b.i FROM a LEFT JOIN b ON a.k <= b.k - 2490 AND a.m >= b.m + 2400 ORDER BY 1, 2 LIMIT 20",
        "0,NULL\n1,NULL\n2,NULL\n3,NULL\n4,NULL\n5,NULL\n6,NULL\n7,NULL\n8,NULL\n9,NULL\n10,NULL\n11,NULL\n12,NULL\n13,NULL\n14,NULL\n15,NULL\n16,NULL\n17,NULL\n18,NULL\n19,NULL",
    );
}

#[test]
fn asof_join_nulls() {
    expect(
        "SELECT t.*, p.v FROM trades t ASOF LEFT JOIN prices p ON t.g = p.g AND t.ts >= p.ts ORDER BY ALL",
        "1,3,a\n1,10,b\n1,NULL,NULL\n2,1,NULL\n2,5,c\nNULL,7,NULL",
    );
}

#[test]
fn asof_join_not_distinct() {
    expect(
        "SELECT t.*, p.v FROM trades t ASOF JOIN prices p ON t.g IS NOT DISTINCT FROM p.g AND t.ts > p.ts ORDER BY ALL",
        "1,3,a\n1,10,b\n1,NULL,b\n2,5,c",
    );
}

#[test]
fn positional_join() {
    expect(
        "SELECT * FROM (SELECT i FROM range(3) t(i)) POSITIONAL JOIN (SELECT s FROM r WHERE i < 5)",
        "0,r0\n1,r1\n2,r2\nNULL,r3\nNULL,r4",
    );
}
